# -*- coding: utf-8 -*-
from pathlib import Path
import base64,mimetypes,html,json,csv,re,shutil,hashlib
D=Path(__file__).resolve().parent; ROOT=D.parent
REF=ROOT/(D.name+'_1'); A=REF/'assets'; DOC=REF/'참고문서'; DOC.mkdir(parents=True,exist_ok=True)
WEB=D/'site_assets'; WEB.mkdir(exist_ok=True)
OLD=ROOT/'20260920 투자제언서'; G=OLD/'@@guide/assets'; IA=OLD/'ir_assets'
def data(p):
 p=Path(p);raw=p.read_bytes();name=hashlib.sha256(raw).hexdigest()[:24]+p.suffix.lower();dest=WEB/name
 if not dest.exists():dest.write_bytes(raw)
 return 'site_assets/'+name
def pic(p,alt='',cls=''):
 return f'<img class="{cls}" src="{data(p)}" alt="{html.escape(alt)}">'
def art():return '<div class="hero-boy"><svg viewBox="0 170 555 670"><image href="'+data(G/'soccer-boy-poses-v2.png')+'" width="1536" height="1024"/></svg></div>'
def card(k,t,p='',cls=''):return f'<article class="card {cls}"><small>{k}</small><h3>{t}</h3><p>{p}</p></article>'
def grid(*items,cols=3):return f'<div class="grid c{cols}">'+''.join(items)+'</div>'
def stat(n,t,p=''):return f'<article class="stat"><strong>{n}</strong><h3>{t}</h3><p>{p}</p></article>'
def band(t):return f'<div class="band">{t}</div>'
def flow(items):return '<div class="flow">'+''.join(f'<article><small>{i+1:02}</small><h3>{t}</h3><p>{p}</p></article>' for i,(t,p) in enumerate(items))+'</div>'
def table(head,rows,cls=''):return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
MCST='https://www.mcst.go.kr/site/s_policy/subPolicy/sportstour/sportstour28.jsp'
PL='https://www.premierleague.com/en/news/58833'
AR='https://www.sports-science.co.jp/arrowz-lab/'
ARG='https://sports-science.co.jp/event/trial-lesson/'
PLCO='https://plco.pro/membership-team'
PLGYM='https://plco.pro/gym'
def link(url,t):return f'<a href="{url}" target="_blank" rel="noopener">{t} ↗</a>'
S=[]
def slide(cat,title,sub,body,source,cls='',note=''):
 i=len(S)+1
