for year,own,members,ramp,partner,pramp,evals,mental,teams,price in inputs:
 r={'year':year,'own_studios':own,'members_per_studio':members,'studio_ramp':ramp,'monthly_membership_krw':price,'partners':partner,'partner_ramp':pramp,'evaluation_buyers':evals,'mental_packages':mental,'team_contracts':teams,'studio_krw':round(own*members*price*12*ramp),'partner_krw':round(partner*12000000*pramp),'evaluation_krw':evals*360000,'mental_krw':mental*800000,'team_krw':teams*3000000};r['total_krw']=sum(r[k] for k in ['studio_krw','partner_krw','evaluation_krw','mental_krw','team_krw']);model.append(r)
