js='''const slides=[...document.querySelectorAll('.slide')];let current=0;function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-hidden',!document.body.classList.contains('overview')&&i!==current)});document.querySelector('#counter').textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;history.replaceState(null,'','#'+(current+1));document.querySelector('#prev').disabled=!current;document.querySelector('#next').disabled=current===slides.length-1}function fit(){document.querySelector('#stage').style.transform=`scale(${Math.min(innerWidth/1600,(innerHeight-62)/900)})`;document.documentElement.style.setProperty('--overview-scale',Math.min((innerWidth-24)/1600,.8))}document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#print').onclick=()=>print();document.querySelector('#overview').onclick=()=>{document.body.classList.toggle('overview');show(current);fit()};const toc=document.querySelector('#toc');document.querySelector('#contents').onclick=()=>toc.showModal();slides.forEach((s,i)=>{let b=document.createElement('button');let n=document.createElement('b');n.textContent=String(i+1).padStart(2,'0');b.append(n,document.createTextNode(s.dataset.title));b.onclick=()=>{document.body.classList.remove('overview');show(i);fit();toc.close()};document.querySelector('.toc-grid').append(b)});document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());const zoom=document.querySelector('#image-dialog');document.querySelectorAll('.zoom').forEach(b=>{b.setAttribute('aria-label',b.querySelector('img').alt+' 확대');b.onclick=()=>{zoom.querySelector('img').src=b.querySelector('img').src;zoom.querySelector('img').alt=b.querySelector('img').alt;zoom.showModal()}});document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});addEventListener('resize',fit);addEventListener('hashchange',()=>show((parseInt(location.hash.slice(1))||1)-1));show((parseInt(location.hash.slice(1))||1)-1);fit();'''
css+=WARM_CSS+REFERENCE_CSS
markup=[]
for r in S:
 title=re.sub('<[^>]+>',' ',r['title']).strip()
 markup.append(f'<section class="slide {r["cls"]}" data-title="{html.escape(title)}" aria-label="{r["no"]}페이지 {html.escape(title)}"><header><span><b>{("IR" if r["no"]==1 else format(r["no"]-1,"02"))}</b> JUNIOR GOLDEN AGE / {r["cat"]}</span>{pic(G/"logo-black.png","MPS")}</header><div class="heading"><h1>{r["title"]}</h1><p class="subtitle">{r["sub"]}</p></div><div class="content">{r["body"]}</div><footer><span class="brand">SPORTS MPS <span class="footer-project">주니어골든에이지</span></span><span class="source">{r["source"]}</span><span class="page">{("IR" if r["no"]==1 else format(r["no"]-1,"02"))}<small> / {len(S)-1}</small></span></footer></section>')
page='<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SPORTS MPS 바이오밴딩 성장관리 플랫폼 투자제안서</title><style>'+fonts+css+'</style></head><body><main id="viewport"><div id="stage">'+''.join(markup)+'</div></main><nav class="controls"><span class="brand">SPORTS MPS INVESTOR DECK</span><button id="prev">← 이전</button><span id="counter" aria-live="polite"></span><button id="next">다음 →</button><button id="contents">목차</button><button id="overview">전체 보기</button><button id="print">PDF / 인쇄</button></nav><dialog id="toc"><button class="close">닫기 ×</button><div class="toc-grid"></div></dialog><dialog id="image-dialog"><button class="close">닫기 ×</button><img alt="확대한 리포트"></dialog><script>'+js+'</script></body></html>'
(D/'index.html').write_text(page)
pret_font='@font-face{font-family:Pretendard;src:url("'+data(IA/'fonts/PretendardVariable.woff2')+'");font-weight:100 900;font-display:block}'
pret_page=page.replace('</style>',pret_font+'body{font-family:Pretendard,sans-serif}</style>')
(D/'index_pretendard.html').write_text(pret_page)
(DOC/'slide_notes.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='body'} for r in S],ensure_ascii=False,indent=2))
with (DOC/'매출모델.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(model[0]));w.writeheader();w.writerows(model)
(DOC/'매출모델.json').write_text(json.dumps(model,ensure_ascii=False,indent=2))
print('Generated',len(S),'slides; revenue scenarios:',[round(r['total_krw']/1e8,3) for r in model])
